window.BGW_SETUP = {"text":{"setup":{"ko":"셋업","en":"Setup","de":"Spielaufbau","fr":"Mise en place","ja":"セットアップ","es":"Preparación","zh":"设置"},"scope":{"ko":"본판 2–4인 기준 · 확장·솔로 제외","en":"Base game, 2–4 players · excludes expansions and solo","de":"Grundspiel, 2–4 Spieler · ohne Erweiterungen/Solo","fr":"Jeu de base, 2–4 joueurs · hors extensions/solo","ja":"基本ゲーム2～4人用・拡張とソロは対象外","es":"Juego base, 2–4 jugadores · sin expansiones ni solitario","zh":"基础游戏2–4人；不含扩展及单人模式"},"item":{"ko":"준비 항목","en":"Setup item","de":"Vorbereitung","fr":"Élément","ja":"準備項目","es":"Elemento","zh":"准备项目"},"p2":{"ko":"2인","en":"2 players","de":"2 Spieler","fr":"2 joueurs","ja":"2人","es":"2 jugadores","zh":"2人"},"p3":{"ko":"3인","en":"3 players","de":"3 Spieler","fr":"3 joueurs","ja":"3人","es":"3 jugadores","zh":"3人"},"p4":{"ko":"4인","en":"4 players","de":"4 Spieler","fr":"4 joueurs","ja":"4人","es":"4 jugadores","zh":"4人"},"common":{"ko":"공통 준비","en":"Common setup","de":"Gemeinsamer Aufbau","fr":"Préparation commune","ja":"共通の準備","es":"Preparación común","zh":"共同准备"},"board":{"ko":"게임판·타일 배치","en":"Board and tile spaces","de":"Spielplan und Plättchenfelder","fr":"Plateau et cases de tuiles","ja":"ボードとタイル配置","es":"Tablero y espacios","zh":"主板与板块位置"},"b2":{"ko":"2·3인 면: 안쪽 일반 타일 12칸 + 검은 저장소 4칸","en":"2/3-player side: 12 inner regular spaces + 4 black-depot spaces","de":"2/3-Spieler-Seite: 12 innere Felder + 4 schwarze Depotfelder","fr":"Face 2/3 joueurs : 12 cases intérieures + 4 cases noires","ja":"2・3人面：内側の通常12マス＋黒い集積所4マス","es":"Cara 2/3 jugadores: 12 espacios interiores + 4 negros","zh":"2/3人面：内侧普通12格＋黑色仓库4格"},"b3":{"ko":"2·3인 면: 2인용 칸에 더해 ‘3’ 표시 8칸도 사용","en":"2/3-player side: use the 2-player spaces plus all eight spaces marked 3","de":"2/3-Spieler-Seite: 2-Spieler-Felder plus acht mit 3 markierte Felder","fr":"Face 2/3 joueurs : cases à 2 joueurs plus les huit cases marquées 3","ja":"2・3人面：2人用に加え「3」の8マスも使用","es":"Cara 2/3 jugadores: espacios de 2 más los ocho marcados 3","zh":"2/3人面：在2人位置外加标有3的8格"},"b4":{"ko":"4인 면: 일반 저장소 6곳×4칸 + 검은 저장소 8칸","en":"4-player side: 6 regular depots × 4 spaces + 8 black spaces","de":"4-Spieler-Seite: 6 Depots × 4 Felder + 8 schwarze Felder","fr":"Face 4 joueurs : 6 dépôts × 4 cases + 8 cases noires","ja":"4人面：通常6か所×4マス＋黒い集積所8マス","es":"Cara de 4: 6 depósitos × 4 espacios + 8 negros","zh":"4人面：6个普通仓库×4格＋黑色8格"},"depot6":{"ko":"6번 저장소 예외","en":"Depot 6 exception","de":"Sonderfall Depot 6","fr":"Exception du dépôt 6","ja":"集積所6の例外","es":"Excepción del depósito 6","zh":"6号仓库例外"},"normal":{"ko":"인쇄된 색상대로 보충","en":"Refill by printed colors","de":"Nach aufgedruckter Farbe auffüllen","fr":"Remplir selon les couleurs imprimées","ja":"印刷された色で補充","es":"Reponer según colores impresos","zh":"按印刷颜色补充"},"b3swap":{"ko":"진초록 칸: A·C·E 단계는 성, B·D 단계는 광산","en":"Dark-green space: castle in A/C/E, mine in B/D","de":"Dunkelgrünes Feld: Burg in A/C/E, Mine in B/D","fr":"Case vert foncé : château en A/C/E, mine en B/D","ja":"濃緑マス：A・C・Eは城、B・Dは鉱山","es":"Espacio verde oscuro: castillo en A/C/E, mina en B/D","zh":"深绿格：A/C/E阶段为城堡，B/D为矿山"},"workers":{"ko":"시작 일꾼 · 선부터 시계방향","en":"Starting workers · clockwise from first player","de":"Startarbeiter · im Uhrzeigersinn ab Startspieler","fr":"Ouvriers initiaux · depuis le premier, sens horaire","ja":"初期労働者・先手から時計回り","es":"Trabajadores iniciales · desde el primero, sentido horario","zh":"起始工人：从首位顺时针"},"bcommon":{"ko":"각자 성 1개, 무작위 상품 3개, 은화 1개, 자기 색 주사위 2개를 받습니다.\n상품은 A–E 단계용으로 5개씩 5더미를 만듭니다.\n다리 첫 칸에 순서 말을 쌓습니다. 선 플레이어가 맨 위입니다.\n선 플레이어가 흰 주사위를 받습니다.","en":"Each player takes 1 castle, 3 random goods, 1 silverling and 2 dice in their color.\nMake five stacks of five goods, one for each phase A–E.\nStack the turn-order markers on the first bridge space, first player on top.\nThe first player takes the white die.","de":"Jeder Spieler nimmt 1 Burg, 3 zufällige Waren, 1 Silberling und 2 Würfel seiner Farbe.\nFür die Phasen A–E je einen Stapel aus 5 Waren bilden.\nReihenfolgemarker auf das erste Brückenfeld stapeln, Startspieler oben.\nDer Startspieler erhält den weißen Würfel.","fr":"Chaque joueur prend 1 château, 3 marchandises aléatoires, 1 pièce et 2 dés de sa couleur.\nFormer cinq piles de cinq marchandises, une par phase A–E.\nEmpiler les marqueurs d’ordre sur la première case du pont, premier joueur au sommet.\nLe premier joueur prend le dé blanc.","ja":"各自、城1枚・無作為の商品3枚・銀貨1枚・自分の色のダイス2個を受け取ります。\nA～Eの各フェイズ用に、商品5枚ずつの山を5つ作ります。\n橋の1マス目に手番マーカーを重ね、先手を一番上にします。\n先手が白ダイスを受け取ります。","es":"Cada jugador toma 1 castillo, 3 mercancías aleatorias, 1 moneda y 2 dados de su color.\nForma cinco pilas de cinco mercancías, una para cada fase A–E.\nApila los marcadores de turno en la primera casilla del puente, el primer jugador encima.\nEl primer jugador recibe el dado blanco.","zh":"每人拿1座城堡、3个随机货物、1枚银币和2枚自己颜色的骰子。\n为A–E每个阶段各准备一堆5个货物。\n在桥的第1格叠放顺序标记，首位玩家在最上面。\n首位玩家拿白骰。"},"dice":{"ko":"사용 주사위 수","en":"Dice in play","de":"Würfelanzahl","fr":"Nombre de dés","ja":"使用ダイス数","es":"Dados en juego","zh":"使用骰子数"},"order":{"ko":"순서 타일","en":"Turn-order tiles","de":"Reihenfolgeplättchen","fr":"Tuiles d’ordre","ja":"手番順タイル","es":"Losetas de orden","zh":"顺序板块"},"o2":{"ko":"뒷면 2인 표시 세트 · 차례 1→2→2→1","en":"Use the 2-player set · order 1→2→2→1","de":"2-Spieler-Satz · Folge 1→2→2→1","fr":"Lot 2 joueurs · ordre 1→2→2→1","ja":"裏が2人用の組・順番1→2→2→1","es":"Juego para 2 · orden 1→2→2→1","zh":"使用2人套组；顺序1→2→2→1"},"o3":{"ko":"뒷면 3인 표시 세트 · 차례 1→2→3→3→2→1","en":"Use the 3-player set · order 1→2→3→3→2→1","de":"3-Spieler-Satz · Folge 1→2→3→3→2→1","fr":"Lot 3 joueurs · ordre 1→2→3→3→2→1","ja":"裏が3人用の組・順番1→2→3→3→2→1","es":"Juego para 3 · orden 1→2→3→3→2→1","zh":"使用3人套组；顺序1→2→3→3→2→1"},"o4":{"ko":"뒷면 4인 표시 세트 · 차례 1→2→3→4→4→3→2→1","en":"Use the 4-player set · order 1→2→3→4→4→3→2→1","de":"4-Spieler-Satz · Folge 1→2→3→4→4→3→2→1","fr":"Lot 4 joueurs · ordre 1→2→3→4→4→3→2→1","ja":"裏が4人用の組・順番1→2→3→4→4→3→2→1","es":"Juego para 4 · orden 1→2→3→4→4→3→2→1","zh":"使用4人套组；顺序1→2→3→4→4→3→2→1"},"guest":{"ko":"최초 무료 손님 선택 순서","en":"Initial free guest selection","de":"Ersten kostenlosen Gast wählen","fr":"Choix du premier client gratuit","ja":"最初の無料客の選択順","es":"Elección del primer huésped gratis","zh":"首位免费客人选择顺序"},"gcommon":{"ko":"선 플레이어를 무작위로 정하고 시계 방향으로 순서 타일을 나눕니다.\n각자 10크로네와 커피·와인·케이크·슈트루델 1개씩을 받습니다.\n각자 직원 카드 6장을 받아 드래프트합니다.\n손님 카드 5장을 공개합니다.\n목표 타일과 황제 타일은 A·B·C에서 1개씩 사용합니다.\n마지막 플레이어부터 반시계 방향으로 무료 손님을 1명씩 고르고, 고를 때마다 보충합니다.\n각자 객실을 최대 3개 준비합니다. 왼쪽 아래부터 인접하게, 색을 맞추고 비용을 냅니다.","en":"Choose a random first player and hand out order tiles clockwise.\nEach player takes 10 krones and one each of coffee, wine, cake and strudel.\nEach player takes 6 staff cards and drafts them.\nReveal 5 guest cards.\nUse one objective tile and one emperor tile from each of A, B and C.\nStarting with the last player and going counterclockwise, each player takes one free guest; refill after each pick.\nEach player prepares up to 3 rooms: start bottom-left, keep them adjacent and color-matched, and pay their costs.","de":"Startspieler zufällig bestimmen und Reihenfolgeplättchen im Uhrzeigersinn verteilen.\nJeder nimmt 10 Kronen und je 1 Kaffee, Wein, Torte und Strudel.\nJeder nimmt 6 Personalkarten und draftet sie.\n5 Gästekarten offen auslegen.\nJe ein Ziel- und Kaiserplättchen aus A, B und C verwenden.\nAb dem letzten Spieler gegen den Uhrzeigersinn je einen kostenlosen Gast wählen; nach jeder Wahl nachfüllen.\nJeder bereitet bis zu 3 Zimmer vor: ab unten links, benachbart und farbgleich; Kosten bezahlen.","fr":"Désigner un premier joueur au hasard et distribuer les tuiles d’ordre dans le sens horaire.\nChacun prend 10 couronnes et un café, un vin, un gâteau et un strudel.\nChacun prend 6 cartes Personnel et les drafte.\nRévéler 5 cartes Client.\nUtiliser un objectif et une tuile empereur de chacun des niveaux A, B et C.\nEn commençant par le dernier joueur, dans le sens antihoraire, chacun choisit un client gratuit ; remplacer après chaque choix.\nChacun prépare jusqu’à 3 chambres : depuis le bas à gauche, adjacentes et de la bonne couleur, en payant leur coût.","ja":"先手を無作為に決め、時計回りに順番タイルを配ります。\n各自10クローネと、コーヒー・ワイン・ケーキ・シュトゥルーデルを1個ずつ受け取ります。\n各自スタッフカード6枚を受け取り、ドラフトします。\n客カード5枚を公開します。\n目標タイルと皇帝タイルはA・B・Cから1枚ずつ使います。\n最後の手番から反時計回りに無料の客を1枚ずつ選び、選ぶたびに補充します。\n各自客室を最大3室準備します。左下から隣接させ、色を合わせ、費用を払います。","es":"Elige al azar al jugador inicial y reparte las losetas de orden en sentido horario.\nCada jugador recibe 10 coronas y un café, un vino, un pastel y un strudel.\nCada jugador recibe 6 cartas de personal y las draftea.\nRevela 5 cartas de huésped.\nUsa un objetivo y una loseta de emperador de cada nivel A, B y C.\nEmpezando por el último jugador, en sentido antihorario, cada uno elige un huésped gratis; repón tras cada elección.\nCada jugador prepara hasta 3 habitaciones: desde abajo a la izquierda, adyacentes y del color correcto, pagando su coste.","zh":"随机决定首位玩家，按顺时针分配顺序板块。\n每人拿10克朗，以及咖啡、酒、蛋糕、卷饼各1个。\n每人拿6张员工卡并进行轮抽。\n公开5张客人卡。\n目标板块和皇帝板块从A、B、C中各用1个。\n从最后一位玩家开始逆时针，每人选1位免费客人，每选一次就补充。\n每人最多准备3间客房：从左下开始，相邻、同色，并支付费用。"},"oasis":{"ko":"오아시스 트랙의 초기 케시 · 1인당","en":"Initial oasis-track keshis · per player","de":"Start-Keshis der Oasenleiste · pro Spieler","fr":"Keshis initiaux de piste oasis · par joueur","ja":"オアシストラック初期ケシ・1人分","es":"Keshis iniciales de oasis · por jugador","zh":"绿洲轨起始凯希：每人"},"draw":{"ko":"케시 추첨 준비","en":"Prepare the keshi draw","de":"Keshi-Ziehung vorbereiten","fr":"Préparer le tirage","ja":"ケシ抽選の準備","es":"Preparar el sorteo","zh":"抽取凯希准备"},"drawrule":{"ko":"노랑·보라·주황·갈색을 제외한 8색을 1개씩 주머니에 넣고 추첨. 뽑은 케시는 오아시스 트랙의 케시 칸에 원하는 순서로 배치","en":"Bag one keshi of each of the eight colors except yellow/purple/orange/brown. Draw and place on the oasis-track keshi spaces in any order.","de":"Je einen Keshi der acht Farben außer Gelb/Lila/Orange/Braun in den Beutel. Ziehen und beliebig auf den Keshi-Feldern der Oasenleiste anordnen.","fr":"Mettre un keshi des huit couleurs sauf jaune/violet/orange/brun dans le sac. Tirer puis placer librement sur les cases keshi de la piste oasis.","ja":"黄・紫・橙・茶を除く8色を各1個袋へ。引いたケシをオアシストラックのケシ欄に任意の順で配置。","es":"Poner en la bolsa uno de los ocho colores salvo amarillo/morado/naranja/marrón. Extraer y colocar en cualquier orden en las casillas keshi de oasis.","zh":"除黄、紫、橙、棕外8色各1入袋。抽取后任意顺序放在绿洲轨凯希格。"},"mcommon":{"ko":"각자 10점, 물·대추·디나르 1개씩을 받습니다.\n각자 12색 케시 각 1개, 오아시스 6개, 식량공급 타일 3개를 받습니다. 첫 계절용 1개는 공개합니다.\n두루마리는 종류별 3더미, 사치품은 5더미를 만듭니다.\n교환소 3개와 계절별 강 타일 1개씩을 준비합니다.\n공방마다 성문 8개를 놓습니다.\n선 플레이어를 무작위로 정합니다.","en":"Each player takes 10 VP and one each of water, date and dinar.\nEach player takes one keshi of each of the 12 colors, 6 oases and 3 provision tiles; reveal one for season 1.\nMake 3 scroll stacks per type and 5 luxury stacks.\nPrepare 3 exchange offices and one river tile per season.\nPlace 8 gates at each workshop.\nChoose a random first player.","de":"Jeder Spieler nimmt 10 Punkte und je 1 Wasser, Dattel und Dinar.\nJeder nimmt je einen Keshi aller 12 Farben, 6 Oasen und 3 Versorgungskärtchen; eines für Saison 1 aufdecken.\nJe Schriftrollentyp 3 Stapel und 5 Luxuswarenstapel bilden.\n3 Wechselstuben und je Saison 1 Flussplättchen bereitlegen.\nAn jede Werkstatt 8 Tore legen.\nStartspieler zufällig bestimmen.","fr":"Chaque joueur prend 10 PV et une eau, une datte et un dinar.\nChacun prend un keshi de chacune des 12 couleurs, 6 oasis et 3 tuiles provision ; en révéler une pour la saison 1.\nFormer 3 piles par type de parchemin et 5 piles de luxe.\nPréparer 3 bureaux de change et une tuile rivière par saison.\nPlacer 8 portes à chaque atelier.\nDésigner un premier joueur au hasard.","ja":"各自10点と、水・ナツメヤシ・ディナールを1個ずつ受け取ります。\n各自12色のケシ各1個、オアシス6枚、供給タイル3枚を受け取り、第1季節用の1枚を公開します。\n巻物は種類別に3山、高級品は5山作ります。\n両替所3枚と、季節ごとの川タイル1枚を準備します。\n工房ごとに門を8枚置きます。\n先手を無作為に決めます。","es":"Cada jugador recibe 10 PV y un agua, un dátil y un dinar.\nCada jugador recibe un keshi de cada uno de los 12 colores, 6 oasis y 3 losetas de provisiones; revela una para la estación 1.\nForma 3 pilas por tipo de pergamino y 5 pilas de lujo.\nPrepara 3 casas de cambio y una loseta de río por estación.\nColoca 8 puertas en cada taller.\nElige al azar al jugador inicial.","zh":"每人拿10分，以及水、椰枣、第纳尔各1个。\n每人拿12色凯希各1个、6个绿洲和3个供给板块；公开其中1个用于第一季。\n卷轴每类做3堆，奢侈品做5堆。\n准备3个兑换所，以及每季1个河流板块。\n每个工坊放8个门。\n随机决定首位玩家。"},"noResults":{"ko":"검색 결과가 없습니다.","en":"No matching setup entries.","de":"Keine passenden Einträge.","fr":"Aucun résultat.","ja":"該当する項目はありません。","es":"Sin resultados.","zh":"无匹配结果。"},"module":{"ko":"모듈","en":"Module","de":"Modul","fr":"Module","ja":"モジュール","es":"Módulo","zh":"模块"},"quickSetup":{"ko":"간단 셋업","en":"Quick setup","de":"Kurzaufbau","fr":"Préparation rapide","ja":"簡単な準備","es":"Preparación rápida","zh":"简要设置"},"mscope":{"ko":"본판 2–4인 · 확장 1·2 모듈 준비 포함 · 솔로 제외","en":"Base game, 2–4 players · expansion 1 & 2 module setup · excludes solo","de":"Grundspiel, 2–4 Spieler · Module aus Erweiterung 1 und 2 · ohne Solo","fr":"Base, 2–4 joueurs · préparation des modules des extensions 1 et 2 · hors solo","ja":"基本ゲーム2～4人・拡張1と2の準備を含む・ソロ除外","es":"Base, 2–4 jugadores · módulos de expansiones 1 y 2 · sin solitario","zh":"基础游戏2–4人；含扩展1、2模块准备；不含单人"},"mexp1":{"ko":"확장 1 · 낙타와 유목민","en":"Expansion 1 · Camels & Nomads","de":"Erweiterung 1 · Camels & Nomads","fr":"Extension 1 · Camels & Nomads","ja":"拡張1 · Camels & Nomads","es":"Expansión 1 · Camels & Nomads","zh":"扩展1 · Camels & Nomads"},"mexp1Intro":{"ko":"6개 모듈은 자유롭게 조합합니다. 처음에는 유목민 또는 낙타 중 하나부터 시작하는 것을 권장합니다. 선택하지 않은 모듈이 필요한 타일은 준비에서 제외하세요.","en":"Combine the six modules freely. For a first game, start with either Nomads or Camels. Remove tiles requiring a module you are not using.","de":"Die sechs Module sind frei kombinierbar. Zum Einstieg Nomads oder Camels wählen. Plättchen ausschließen, die ein nicht verwendetes Modul benötigen.","fr":"Les six modules se combinent librement. Pour débuter, choisissez Nomads ou Camels. Retirez les tuiles nécessitant un module non utilisé.","ja":"6モジュールは自由に組み合わせられます。初回は遊牧民かラクダの一方から始めるのを推奨。使用しないモジュールが必要なタイルは除きます。","es":"Combina libremente los seis módulos. Para empezar, usa Nómadas o Camellos. Retira las losetas que requieran módulos no utilizados.","zh":"6个模块可自由组合。初次建议从游牧民或骆驼之一开始。移除需要未使用模块的板块。"},"mnomads":{"ko":"유목민","en":"Nomads","de":"Nomaden","fr":"Nomades","ja":"遊牧民","es":"Nómadas","zh":"游牧民"},"mnomadsSetup":{"ko":"유목민 보드를 큐브 타워 옆에 놓고 나무 유목민 케시 20개를 공용 공급처로 올립니다. 에센셜 에디션은 종이 유목민 케시도 함께 준비합니다.","en":"Place the nomad board beside the cube tower and put all 20 wooden nomad keshis on it as the supply. In Essential Edition, also place the cardboard nomad keshis there.","de":"Nomadenbrett neben den Würfelturm legen; alle 20 Holz-Nomadenkeshis darauf als Vorrat bereitstellen. In der Essential Edition auch die Papp-Nomadenkeshis dort bereitlegen.","fr":"Placez le plateau des nomades près de la tour et les 20 keshis nomades en bois dessus comme réserve. En Essential Edition, ajoutez les keshis nomades en carton.","ja":"遊牧民ボードをタワーの横に置き、木製の遊牧民ケシ20個を共通のストックにします。Essential Editionでは紙製の遊牧民ケシも用意します。","es":"Coloca el tablero de nómadas junto a la torre y los 20 keshis nómadas de madera encima como reserva. En Essential Edition, añade también los de cartón.","zh":"将游牧民板放在塔旁，20个木制游牧民凯希放于其上作为公共储备。Essential Edition另备纸板游牧民凯希。"},"mcamels":{"ko":"낙타","en":"Camels","de":"Kamele","fr":"Chameaux","ja":"ラクダ","es":"Camellos","zh":"骆驼"},"mcamelsSetup":{"ko":"경주로 3조각을 조립해 게임 보드 옆에 놓습니다. 각자 자기 색 낙타를 관중 열 위의 출발 칸에 놓습니다. 양면 시상 타일 6개 중 3개를 무작위 면으로 골라 쌓고, 나머지는 상자에 넣습니다. 배설물 타일은 지정 칸에 둡니다.\n에센셜: 두루마리는 종류별 같은 높이의 3더미, 사치품은 같은 높이의 5더미로 나누고 맨 위를 공개합니다.","en":"Assemble the three-part racecourse beside the game board. Put each camel on the start space above its matching spectator column. Randomly select 3 of the 6 double-sided award tiles, with random sides up, and stack them; return the rest to the box. Put dung tiles on their marked space.\nEssential: use 3 equal stacks per scroll type and 5 equal luxury stacks, revealing the top tiles.","de":"Die dreiteilige Rennbahn neben das Spielbrett legen. Kamele auf das Startfeld über der eigenen Zuschauer-Spalte stellen. Von 6 doppelseitigen Auszeichnungsplättchen 3 mit zufälliger Seite stapeln; übrige zurücklegen. Dungplättchen auf das vorgesehene Feld legen.\nEssential: je Schriftrollentyp 3 gleich hohe Stapel und 5 gleich hohe Luxuswarenstapel; oberste Plättchen offen.","fr":"Assemblez les 3 parties de la piste près du plateau. Chaque chameau démarre au-dessus de sa colonne de spectateurs. Choisissez 3 des 6 tuiles récompense, faces aléatoires, et empilez-les ; rangez les autres. Placez les crottes sur l’emplacement prévu.\nEssential : 3 piles égales par type de parchemin et 5 piles égales de luxe, tuiles du dessus visibles.","ja":"3パーツの競走路をボードの横に組み立て、自分の観客列の上の開始マスにラクダを置きます。両面の表彰タイル6枚から3枚を面も無作為に選び重ね、残りは箱へ。糞タイルは指定場所に置きます。\nEssential：巻物は種類ごと同じ高さの3山、高級品は5山に分け、各山の一番上を公開します。","es":"Monta la pista de 3 piezas junto al tablero. Cada camello comienza sobre su columna de espectadores. Elige 3 de las 6 losetas de premio con caras aleatorias y apílalas; guarda las demás. Coloca el estiércol en su espacio.\nEssential: 3 pilas iguales por tipo de pergamino y 5 pilas iguales de lujo, con las losetas superiores visibles.","zh":"在主板旁组装3片赛道，各玩家将骆驼放在自己观众列上方的起点。6块双面奖励板随机选3块，随机面朝上叠放，余下收回盒内；粪便板放在指定处。\nEssential：卷轴每类分3个等高堆，奢侈品分5个等高堆，各堆顶板公开。"},"mbuildings":{"ko":"특수 건물","en":"Special Buildings","de":"Sondergebäude","fr":"Bâtiments spéciaux","ja":"特殊建物","es":"Edificios especiales","zh":"特殊建筑"},"mbuildingsSetup":{"ko":"전원이 같은 면을 사용하도록 합의합니다. 건물 8개를 섞어 각자 2개를 뽑고 1개만 선택합니다. 본판의 기본 시작 자원 대신 건물에 표시된 시작 케시·자원을 받으며 배치 보너스도 적용합니다. 노란 두루마리를 섞어 각자 3개 중 1개를 선택하고, 즉시 효과는 바로 처리합니다. 남은 건물은 상자에, 남은 두루마리는 본판처럼 준비합니다.","en":"Agree on one building side for everyone. Shuffle all 8 buildings; each player draws 2 and keeps 1. Take the depicted starting keshi and resources instead of the usual starting resources, applying placement bonuses. Each player draws 3 yellow scrolls and keeps 1; resolve instant effects now. Box unused buildings and set up remaining scrolls normally.","de":"Alle verwenden dieselbe Gebäudeseite. 8 Gebäude mischen; je 2 ziehen und 1 behalten. Angegebene Startkeshis und Ressourcen statt der üblichen Startressourcen nehmen; Platzierungsboni anwenden. Je 3 gelbe Schriftrollen ziehen und 1 behalten, Soforteffekte ausführen. Übrige Gebäude zurücklegen, übrige Schriftrollen normal vorbereiten.","fr":"Convenez d’une même face pour tous. Mélangez les 8 bâtiments ; chacun en pioche 2 et en garde 1. Prenez les keshis et ressources indiqués au lieu des ressources initiales habituelles, avec les bonus de placement. Chacun pioche 3 parchemins jaunes et en garde 1 ; résolvez les effets immédiats. Rangez les bâtiments inutilisés et préparez les parchemins restants normalement.","ja":"全員が使う建物の面を決めます。8枚を混ぜて各自2枚から1枚を選びます。通常の初期資源の代わりに建物に示す初期ケシ・資源を受け取り、配置ボーナスも適用。黄色い巻物を各自3枚引いて1枚を選び、即時効果を処理します。残りの建物は箱へ、巻物は通常どおり準備します。","es":"Acordad usar todos la misma cara. Mezcla los 8 edificios; cada jugador roba 2 y conserva 1. Recibe los keshis y recursos indicados en lugar de los recursos iniciales habituales, aplicando bonos de colocación. Roba 3 pergaminos amarillos y conserva 1; resuelve efectos inmediatos. Guarda edificios sobrantes y prepara los demás pergaminos normalmente.","zh":"全员约定使用同一面。洗混8块建筑，每人抽2选1。以建筑标示的初始凯希与资源代替通常的初始资源，并获得放置奖励。每人抽3块黄色卷轴选1，即时效果立即执行；剩余建筑回盒，卷轴照常准备。"},"mprovisions":{"ko":"새 식량공급 타일","en":"New Provision Tiles","de":"Neue Versorgungsplättchen","fr":"Nouvelles tuiles provision","ja":"新しい食料供給タイル","es":"Nuevas losetas de provisión","zh":"新供给板块"},"mprovisionsSetup":{"ko":"본판·보통(-6점)·어려움(-8점) 타일을 따로 섞습니다. 각자 본판 3개, 보통 1개, 어려움 1개를 받은 뒤 사용할 3개를 선택하고 나머지는 상자에 넣습니다. 선택한 타일은 뒷면으로 놓고 첫 계절용 1개를 공개합니다. 유목민 효과 타일은 유목민 모듈을 사용할 때만 포함합니다.","en":"Shuffle base, moderate (-6) and hard (-8) tiles separately. Each player takes 3 base, 1 moderate and 1 hard tile, selects 3 to use and boxes the rest. Place chosen tiles face down and reveal one for the first season. Include the nomad-effect tile only with the Nomads module.","de":"Grundspiel-, mittlere (-6) und schwere (-8) Plättchen getrennt mischen. Je 3 Grundspiel-, 1 mittleres und 1 schweres Plättchen nehmen, 3 auswählen und übrige zurücklegen. Gewählte verdeckt auslegen, eines für Saison 1 aufdecken. Nomadeneffekt nur mit Nomadenmodul verwenden.","fr":"Mélangez séparément les tuiles de base, modérées (-6) et difficiles (-8). Chacun reçoit 3 de base, 1 modérée et 1 difficile, en choisit 3 et range les autres. Placez-les face cachée et révélez-en une pour la première saison. La tuile liée aux nomades nécessite ce module.","ja":"基本・中級(-6点)・上級(-8点)を別々に混ぜます。各自、基本3枚・中級1枚・上級1枚から使う3枚を選び、残りは箱へ。選んだタイルは裏向きで置き、第1季節用1枚を公開。遊牧民効果のタイルは遊牧民モジュール使用時のみ入れます。","es":"Baraja por separado las losetas base, moderadas (-6) y difíciles (-8). Cada jugador recibe 3 base, 1 moderada y 1 difícil, elige 3 y guarda el resto. Colócalas boca abajo y revela una para la primera estación. Usa la loseta de nómadas solo con ese módulo.","zh":"基础、中等(-6分)、困难(-8分)板块分别洗混。每人取基础3、中等1、困难1，选3块使用，其余回盒。所选面朝下放置，公开首季用1块。游牧民效果板块仅在使用游牧民模块时加入。"},"mluxury":{"ko":"새 사치품","en":"New Luxury Goods","de":"Neue Luxuswaren","fr":"Nouveaux biens de luxe","ja":"新しい高級品","es":"Nuevos bienes de lujo","zh":"新奢侈品"},"mluxurySetup":{"ko":"새 사치품(팔콘·레이스 안장)을 본판 사치품과 섞어 같은 높이의 5더미로 나누고 맨 위를 공개합니다. 유목민 케시를 주는 팔콘은 유목민 모듈이 없으면 제외합니다. 낙타 모듈 없이도 레이스 안장은 사용하며, 그 경우 낙타 전진 대신 자원 최대 2개 할인으로 오아시스 1개를 차지합니다.","en":"Mix Falcons and Race Saddles with the base luxury tiles, form 5 equal stacks and reveal their top tiles. Remove the nomad-granting Falcon if not using Nomads. Race Saddles work without Camels: replace camel movement with claiming one oasis at a discount of up to 2 resources.","de":"Falken und Rennsättel mit den Grundspiel-Luxuswaren mischen; 5 gleich hohe Stapel bilden und oberste Plättchen aufdecken. Ohne Nomaden den Falken mit Nomadenbonus entfernen. Rennsättel ohne Kamele erlauben statt Bewegung eine Oase mit bis zu 2 Ressourcen Rabatt.","fr":"Mélangez faucons et selles de course avec le luxe de base ; formez 5 piles égales, dessus visibles. Sans Nomads, retirez le faucon donnant un nomade. Sans Camels, la selle permet de revendiquer une oasis avec une réduction maximale de 2 ressources au lieu d’avancer.","ja":"ファルコンと競走用の鞍を基本高級品と混ぜ、同じ高さの5山にして上を公開します。遊牧民を獲得するファルコンは遊牧民未使用なら除外。ラクダなしでも鞍は使用でき、移動の代わりに最大2資源割引でオアシス1枚を獲得します。","es":"Mezcla halcones y sillas de carrera con los bienes de lujo base; forma 5 pilas iguales y revela las superiores. Sin Nómadas, retira el halcón que concede un nómada. Sin Camellos, la silla permite reclamar un oasis con hasta 2 recursos de descuento en vez de avanzar.","zh":"猎鹰与赛鞍混入基础奢侈品，分5个等高堆并公开顶板。不使用游牧民时移除给予游牧民的猎鹰。无骆驼模块仍可使用赛鞍，改为以最多减免2资源的费用领取1块绿洲。"},"moases":{"ko":"새 오아시스","en":"New Oasis Tiles","de":"Neue Oasen","fr":"Nouvelles tuiles oasis","ja":"新しいオアシス","es":"Nuevos oasis","zh":"新绿洲"},"moasesSetup":{"ko":"사용 모듈에 맞는 새 타일만 본판 오아시스와 섞습니다. 31–34번은 새 사치품, 35번은 낙타, 36번은 유목민 모듈을 사용할 때 포함합니다. 이후 인원별 오아시스 준비는 본판 규칙을 따릅니다.","en":"Mix only eligible new tiles with the base oases: 31–34 require New Luxury Goods, 35 requires Camels, and 36 requires Nomads. Then follow the base game's player-count setup.","de":"Nur passende neue Oasen ins Grundspiel mischen: 31–34 benötigen neue Luxuswaren, 35 Kamele, 36 Nomaden. Danach den Aufbau nach Spielerzahl des Grundspiels verwenden.","fr":"Mélangez seulement les nouvelles oasis compatibles : 31–34 nécessitent les nouveaux biens de luxe, 35 Camels, 36 Nomads. Suivez ensuite la préparation de base selon le nombre de joueurs.","ja":"使用モジュールに合うタイルだけ基本オアシスと混ぜます。31～34は新高級品、35はラクダ、36は遊牧民使用時に入れます。その後は人数別の基本準備に従います。","es":"Mezcla solo los oasis compatibles con los básicos: 31–34 requieren Nuevos bienes de lujo, 35 Camellos y 36 Nómadas. Después sigue la preparación base según los jugadores.","zh":"仅将适用的新板块混入基础绿洲：31–34需新奢侈品，35需骆驼，36需游牧民模块。随后按基础规则的人数设置准备。"},"mexp1Source":{"ko":"출처: Camels & Nomads 영문 룰북 1–2, 5, 7–8쪽.","en":"Source: Camels & Nomads English rulebook, pp. 1–2, 5, 7–8.","de":"Quelle: englische Anleitung Camels & Nomads, S. 1–2, 5, 7–8.","fr":"Source : règles anglaises Camels & Nomads, p. 1–2, 5, 7–8.","ja":"出典：Camels & Nomads英語ルールブック1～2、5、7～8ページ。","es":"Fuente: reglamento inglés Camels & Nomads, pp. 1–2, 5, 7–8.","zh":"来源：Camels & Nomads英文规则，第1–2、5、7–8页。"},"mexp2":{"ko":"확장 2 · 모듈별 준비","en":"Expansion 2 · Module setup","de":"Erweiterung 2 · Modulaufbau","fr":"Extension 2 · Préparation des modules","ja":"拡張2 · モジュール別の準備","es":"Expansión 2 · Preparación de módulos","zh":"扩展2 · 模块准备"},"mexp2Intro":{"ko":"사용하는 모듈의 준비만본판 셋업에 적용하세요. 아래는 제공된 룰북 이미지에서 확인한 6개 모듈의 요약입니다.","en":"Apply the setup changes for the modules you use. These six summaries are based on the supplied rulebook images.","de":"Nur den Aufbau der verwendeten Module anwenden. Diese sechs Zusammenfassungen basieren auf den bereitgestellten Regelbildern.","fr":"Appliquez les modifications des modules utilisés. Ces six résumés sont tirés des images du livret fournies.","ja":"使用するモジュールの準備だけ基本準備に適用してください。以下は提供されたルール画像で確認した6モジュールの要約です。","es":"Aplica los cambios de los módulos utilizados. Estos seis resúmenes proceden de las imágenes del reglamento facilitadas.","zh":"仅应用所用模块的准备变更。以下6个模块根据提供的规则图片整理。"},"mclosedMadrasa":{"ko":"폐쇄된 마드라사","en":"The Closed Madrasa","de":"Die geschlossene Madrasa","fr":"La madrasa fermée","ja":"閉ざされたマドラサ","es":"La madrasa cerrada","zh":"封闭的宗教学校"},"mclosedMadrasaSetup":{"ko":"마드라사 보드 4조각을 모두 A면으로 조립해 본판 마드라사 위에 놓습니다. B면 또는 A/B 혼합도 가능합니다. 에센셜은 게임 보드 옆에 놓습니다.\n4구역의 표시 칸에 마커 1개씩 둡니다. 그림에 표시된 케시 타일을 회색 두루마리 01/04, 같은 상품색의 더블 케시를 노란 두루마리 07/10, 초록/분홍·청록/빨강 더블 케시를 분홍 두루마리 16에 놓습니다. 본판 두루마리는 상자에 둡니다.","en":"Assemble the four Madrasa pieces with A sides up and cover the base Madrasa. B sides or mixed A/B sides are alternatives. In Essential Edition, place it beside the game board.\nPut one marker on each of the four marked area spaces. Place the pictured keshi tiles on gray scroll 01/04, matching goods-color double-keshi tiles on yellow scroll 07/10, and green/pink and turquoise/red double-keshi tiles on pink scroll 16. Leave base-game scrolls in the box.","de":"Vier Madrasa-Teile mit A nach oben auf die Madrasa des Grundspiels legen; B oder A/B gemischt sind Alternativen. In der Essential Edition daneben legen.\nJe einen Marker auf die vier markierten Felder stellen. Abgebildete Keshiplättchen auf graue Rolle 01/04, Doppel-Warenkeshis auf gelbe Rolle 07/10 und grün/rosa sowie türkis/rot auf rosa Rolle 16 legen. Grundspiel-Schriftrollen bleiben in der Schachtel.","fr":"Assemblez les quatre pièces côté A sur la madrasa de base ; B ou A/B mélangés sont possibles. En Essential Edition, placez-la à côté du plateau.\nUn marqueur sur chacun des quatre emplacements. Placez les keshis illustrés sur le parchemin gris 01/04, les doubles keshis de marchandises sur le jaune 07/10, et vert/rose et turquoise/rouge sur le rose 16. Rangez les parchemins de base.","ja":"4片をA面で組み立て、基本マドラサの上に置きます。B面やA/B混合も可。Essential Editionではボードの横に置きます。\n4区域の指定マスにマーカー各1個。図示のケシタイルは灰色の巻物01/04、同じ商品色のダブルケシは黄色07/10、緑/ピンクと青緑/赤はピンク16に配置。基本巻物は箱に置きます。","es":"Monta las cuatro piezas por el lado A sobre la madrasa base; también admite B o A/B mezclados. En Essential Edition, colócala junto al tablero.\nUn marcador en cada uno de los cuatro espacios. Keshis ilustrados en pergamino gris 01/04, dobles de mercancías en amarillo 07/10, y verde/rosa y turquesa/rojo en rosa 16. Guarda los pergaminos base.","zh":"4片学校板A面朝上盖在基础学校上，也可用B面或混合A/B。Essential Edition放于主板旁。\n4个区域标记位各放1个标记。图示凯希板放于灰卷轴01/04；同色商品双凯希放于黄卷轴07/10；绿/粉、青绿/红双凯希放于粉卷轴16。基础卷轴留在盒内。"},"mgems":{"ko":"보석","en":"Gems","de":"Edelsteine","fr":"Gemmes","ja":"宝石","es":"Gemas","zh":"宝石"},"mgemsSetup":{"ko":"보석상 보드를 본판 옆에 놓고 보석 56개를 섞어 발견면이 위로 보이게 공급처에 둡니다. 서로 다른 색 보석 3개가 나올 때까지 뽑아 판매 칸에 공개하고 나머지는 다시 섞습니다. 새 두루마리 4개·오아시스 2개를 기존 타일과 섞어 평소처럼 준비합니다. 각자 목걸이 보드 1개를 받습니다.\n공개 보석: 각자 관중 1명 보너스 칸에 2개를 쌓습니다. 강 9번째 칸에 1개(매 계절 시작 시 다시 준비), 궁전 계단 12번째·모스크 계단 9번째 칸에 각각 플레이어 수만큼 둡니다.\n비공개 보석: 궁전·모스크의 세 번째 구간을 잇는 주황 연결선에 플레이어 수만큼 둡니다. 개인 보드에는 각각 1개씩 총 6개: 활성화 오아시스 보너스 트랙 4번째 칸(케시를 위에 놓음), 사하라 왼쪽 마지막·오른쪽 두 번째 오아시스, 수크 앞 상품색 성문 칸, 대추야자 밭 4번째·7번째 케시 칸.","en":"Place the gem dealer beside the main board. Mix all 56 gems, discovery side up. Draw until 3 different colors can be displayed for sale; remix the others. Mix 4 new scrolls and 2 oases into their respective tiles and set up normally. Each player takes one necklace board.\nFace up: stack 2 gems on each player's one-spectator bonus space; place 1 on river space 9 (renew each season), and one per player on palace step 12 and mosque step 9, separately.\nFace down: place one per player on the orange link between the third palace/mosque sections. Each player board gets 6: activated-oasis bonus space 4 (keshi on top), last left and second right Sahara oasis, goods-color gate space in front of the Souk, and date-orchard keshi spaces 4 and 7.","de":"Edelsteinhändler neben das Brett legen. 56 Edelsteine mit Entdeckungsseite oben mischen; 3 verschiedene Farben für das Angebot ziehen, übrige zurückmischen. 4 neue Rollen und 2 Oasen untermischen und normal vorbereiten. Je ein Halskettenbrett nehmen.\nOffen: je 2 auf das 1-Zuschauer-Bonusfeld; 1 auf Flussfeld 9 (jede Saison erneuern); je Spieler 1 auf Palaststufe 12 und Moscheestufe 9.\nVerdeckt: je Spieler 1 auf die orange Verbindung der dritten Treppenabschnitte. Je Spielerbrett 6: Oasenbonusfeld 4 (Keshi darauf), letzte linke und zweite rechte Sahara-Oase, Warenfarb-Torfeld vor dem Souk, Dattelfeld-Keshifelder 4 und 7.","fr":"Placez le marchand à côté du plateau. Mélangez les 56 gemmes, côté découverte visible. Piochez 3 couleurs différentes pour la vente ; remélangez les autres. Ajoutez 4 parchemins et 2 oasis aux tuiles correspondantes, préparation habituelle. Une planche collier chacun.\nVisibles : 2 empilées sur le bonus à 1 spectateur de chacun ; 1 sur rivière 9 (renouvelée chaque saison) ; une par joueur sur palais 12 et mosquée 9, séparément.\nCachées : une par joueur sur la liaison orange des troisièmes sections. 6 par plateau personnel : bonus oasis 4 (keshi dessus), dernière oasis gauche et deuxième droite du Sahara, porte des couleurs marchandises devant le souk, cases dattes 4 et 7.","ja":"宝石商をボードの横に置き、宝石56個を発見面を上にして混ぜます。異なる3色が売場に並ぶまで引き、残りは混ぜ直します。新巻物4枚・オアシス2枚を対応するタイルに混ぜ、通常準備。各自ネックレスボード1枚。\n公開：各自の観客1人ボーナスに2個を重ね、川9マス目に1個（毎季節再準備）。宮殿12段目・モスク9段目にそれぞれ人数分。\n非公開：両階段の第3区域を結ぶオレンジ線に人数分。各個人ボードには6個：活性化オアシスのボーナス4マス目（上にケシ）、サハラ左最後・右2番目、スーク前の商品色の門、ナツメヤシ畑のケシ4・7番目。","es":"Coloca el mercader junto al tablero. Mezcla las 56 gemas, lado de descubrimiento visible. Saca 3 colores distintos para la venta y remezcla las demás. Añade 4 pergaminos y 2 oasis a sus respectivos grupos; prepara normalmente. Un tablero de collar por jugador.\nVisibles: 2 apiladas en el bono de 1 espectador de cada jugador; 1 en río 9 (renovar cada estación); una por jugador en palacio 12 y mezquita 9, por separado.\nOcultas: una por jugador en la conexión naranja de las terceras secciones. 6 en cada tablero personal: bono oasis 4 (keshi encima), último oasis izquierdo y segundo derecho del Sahara, puerta de colores de mercancías frente al zoco y casillas de dátiles 4 y 7.","zh":"宝石商板放在主板旁，56颗宝石发现面朝上混合。抽到3种不同颜色用于销售，其余混回储备。新卷轴4、新绿洲2混入对应板块照常准备。每人领1块项链板。\n公开：每人1观众奖励位叠2颗；河道第9格放1颗（每季开始重置）；宫殿第12阶、清真寺第9阶各放玩家人数的宝石。\n隐藏：连接两座阶梯第3区的橙线上放玩家人数的宝石。每人板上共6颗：激活绿洲奖励轨第4格（凯希叠于上）、撒哈拉左路最后及右路第2绿洲、市场前商品色城门格、椰枣园第4及第7凯希格。"},"mexperts":{"ko":"전문가","en":"The Experts","de":"Die Experten","fr":"Les experts","ja":"専門家","es":"Los expertos","zh":"专家"},"mexpertsSetup":{"ko":"전문가 타일 12개를 섞어 큐브 타워 옆에 뒷면으로 쌓습니다. 전문가 보드를 타워 옆에 놓고 표시된 칸에 전문가 케시 5개를 배치합니다. 새 두루마리 2개·오아시스 2개를 기존 해당 타일에 섞어 평소처럼 준비합니다.","en":"Shuffle the 12 expert tiles into a face-down stack beside the cube tower. Place the expert board there and put the 5 expert keshis on its marked spaces. Mix 2 new scrolls and 2 oases into their respective tiles and set up normally.","de":"12 Expertenplättchen mischen und verdeckt neben den Würfelturm stapeln. Expertenbrett daneben legen, 5 Expertenkeshis auf markierte Felder stellen. 2 neue Rollen und 2 Oasen untermischen und normal vorbereiten.","fr":"Mélangez les 12 experts et empilez-les face cachée près de la tour. Placez le plateau expert à côté et ses 5 keshis sur les emplacements marqués. Ajoutez 2 parchemins et 2 oasis aux tuiles correspondantes, préparation habituelle.","ja":"専門家タイル12枚を混ぜ、タワーの横に裏向きの山にします。専門家ボードを横に置き、指定マスに専門家ケシ5個。新巻物2枚・オアシス2枚を対応タイルに混ぜて通常どおり準備します。","es":"Baraja los 12 expertos y apílalos boca abajo junto a la torre. Coloca allí su tablero con 5 keshis expertos en los espacios marcados. Mezcla 2 pergaminos y 2 oasis nuevos con sus respectivos grupos y prepara normalmente.","zh":"12块专家板洗混后背面朝上叠于塔旁。专家板放在旁边，标记位置放5个专家凯希。新卷轴2、新绿洲2混入对应板块照常准备。"},"malms":{"ko":"자선 타일(교환소)","en":"Alms Tiles (Exchange Office)","de":"Almosenplättchen (Wechselstube)","fr":"Tuiles aumône (bureau de change)","ja":"施しタイル（両替所）","es":"Losetas de limosna (casa de cambio)","zh":"施舍板块（兑换所）"},"malmsSetup":{"ko":"자선 타일 12개를 번호로 나눕니다. 7–12번 6개를 섞어 본판 교환소 칸에 뒷면으로 놓습니다. 1–6번 6개를 따로 섞어 그 위에 뒷면으로 쌓고 맨 위 1개만 공개합니다.","en":"Separate the 12 alms tiles by number. Shuffle tiles 7–12 and stack them face down on the exchange-office space. Separately shuffle 1–6 and stack them face down on top; reveal only the top tile.","de":"12 Almosenplättchen nach Nummer trennen. 7–12 mischen, verdeckt auf das Wechselstubenfeld stapeln. 1–6 separat mischen und verdeckt darauf stapeln; nur das oberste aufdecken.","fr":"Séparez les 12 tuiles par numéro. Mélangez 7–12 et empilez-les face cachée sur le bureau de change. Mélangez 1–6 séparément, empilez-les au-dessus et révélez seulement la première.","ja":"12枚を番号で分け、7～12の6枚を混ぜて両替所に裏向きで重ねます。1～6の6枚も別に混ぜてその上に重ね、一番上の1枚だけ公開します。","es":"Divide las 12 losetas por número. Baraja 7–12 y apílalas boca abajo en la casa de cambio. Baraja 1–6 aparte y apílalas encima; revela solo la superior.","zh":"12块按编号分组。7–12号6块洗混，背面朝上放在兑换所。1–6号另行洗混并叠在上方，只公开最顶1块。"},"mexp2Source":{"ko":"출처: 제공된 확장 2 영문 룰북 이미지 7장.","en":"Source: seven supplied images of the expansion 2 English rulebook.","de":"Quelle: sieben bereitgestellte Bilder der englischen Anleitung zu Erweiterung 2.","fr":"Source : sept images fournies des règles anglaises de l’extension 2.","ja":"出典：提供された拡張2英語ルール画像7枚。","es":"Fuente: siete imágenes del reglamento inglés de expansión 2.","zh":"来源：提供的扩展2英文规则图片7张。"},"msecondhand":{"ko":"중고 상점","en":"Second-Hand Shop","de":"Gebrauchtwarenladen","fr":"Boutique d’occasion","ja":"中古品店","es":"Tienda de segunda mano","zh":"二手商店"},"msecondhandSetup":{"ko":"중고 상점 보드를 게임 보드 옆에 놓고 중고 표시 타일 20개를 지정 칸에 둡니다. 나머지 상점 칸은 비워 둡니다. 각자 자기 색 제안 타일 5개(두루마리용 4개·오아시스용 1개)를 받습니다. 새 오아시스 2개를 본판 오아시스에 섞습니다.","en":"Place the second-hand shop beside the game board and put the 20 used tiles on their designated space. Leave all other shop spaces empty. Each player takes the 5 offer tiles in their color: 4 for scrolls and 1 for oases. Mix the 2 new oases with the base-game oases.","de":"Gebrauchtwarenladen neben das Spielbrett legen, 20 Gebrauchtplättchen auf das vorgesehene Feld legen. Andere Ladenfelder bleiben leer. Je Spieler 5 Angebotsplättchen seiner Farbe: 4 für Schriftrollen, 1 für Oasen. 2 neue Oasen ins Grundspiel mischen.","fr":"Placez la boutique près du plateau et les 20 tuiles d’occasion sur l’emplacement prévu. Les autres cases restent vides. Chacun reçoit 5 tuiles offre de sa couleur : 4 pour les parchemins, 1 pour les oasis. Mélangez les 2 nouvelles oasis aux oasis de base.","ja":"中古品店をゲームボードの横に置き、使用済みタイル20枚を指定場所に置きます。他の店のマスは空けます。各自、自分の色の提示タイル5枚（巻物用4枚・オアシス用1枚）を受け取ります。新オアシス2枚を基本オアシスに混ぜます。","es":"Coloca la tienda junto al tablero y las 20 losetas de usado en su espacio. Deja vacíos los demás espacios. Cada jugador recibe 5 losetas de oferta de su color: 4 para pergaminos y 1 para oasis. Mezcla los 2 nuevos oasis con los básicos.","zh":"二手商店放在主板旁，20块使用标记放于指定位置，其余商店格保持空置。每人领取自己颜色的5块报价板：卷轴用4块、绿洲用1块。2块新绿洲混入基础绿洲。"},"mgifts":{"ko":"사치품 · 선물","en":"Luxury Goods: Gifts","de":"Luxuswaren: Geschenke","fr":"Biens de luxe : cadeaux","ja":"高級品：贈り物","es":"Bienes de lujo: regalos","zh":"奢侈品：礼物"},"mgiftsSetup":{"ko":"선물 타일 10개를 섞어 별도의 1더미로 만들고, 기존 사치품 5더미 아래쪽에 놓습니다. 맨 위 타일 1개만 공개합니다. 기존 사치품 더미에는 섞지 않습니다.","en":"Shuffle all 10 gift tiles into one separate stack below the existing five luxury-goods stacks. Reveal only the top gift. Do not mix gifts into the luxury-goods stacks.","de":"Alle 10 Geschenkplättchen mischen und als eigenen Stapel unterhalb der fünf Luxuswarenstapel ablegen. Nur das oberste Geschenk aufdecken. Nicht in die Luxuswarenstapel mischen.","fr":"Mélangez les 10 cadeaux en une pile séparée sous les cinq piles de luxe existantes. Révélez seulement le premier cadeau. Ne les mélangez pas aux piles de luxe.","ja":"贈り物タイル10枚を混ぜ、既存の高級品5山の下側に別の1山として置きます。一番上の1枚だけ公開。高級品の山には混ぜません。","es":"Baraja los 10 regalos en una pila aparte debajo de las cinco pilas de lujo existentes. Revela solo el regalo superior. No los mezcles con las pilas de lujo.","zh":"10块礼物洗混成独立一堆，放在现有5堆奢侈品的下方。仅公开顶端1块，不混入奢侈品堆。"},"p5":{"ko":"5인","en":"5 players","de":"5 Spieler","fr":"5 joueurs","ja":"5人","es":"5 jugadores","zh":"5人"},"players":{"ko":"{n}인","en":"{n} players","de":"{n} Spieler","fr":"{n} joueurs","ja":"{n}人","es":"{n} jugadores","zh":"{n}人"},"escope":{"ko":"본판 2–5인 기준 · 콜드 워 모듈 제외","en":"Base game, 2–5 players · excludes the Cold War module"},"epollution":{"ko":"임팩트 트랙 칸마다 오염 토큰","en":"Pollution tokens on each Global Impact space"},"eneutral":{"ko":"중립 일꾼 (구조물 시장)","en":"Neutral Workers (Structure markets)"},"eneutral2":{"ko":"안 쓰는 색 3개 · 정부·산업·상업 시장에 1개씩, 게임 내내 고정","en":"3 of an unused color · 1 on each Government, Industry and Commerce market for the whole game"},"enone":{"ko":"없음","en":"None"},"emoney":{"ko":"차례 순서별 시작 자금","en":"Starting money by turn order"},"ecommon":{"ko":"보드 옆에 자원·주사위·오염·유정 토큰 더미를 만듭니다.\n카드 덱 6종과 업적 타일을 각각 섞습니다.\n글로벌 임팩트 초기 3장 → 후기 3장 순으로 보드 아래에 뒷면으로 놓습니다. 나머지는 상자에 넣습니다.\n구조물 시장 3곳을 오른쪽부터 해당 덱 3장으로 채웁니다.\n업적 3개를 앞면으로 놓습니다.\n각자 점수 트랙 0칸과 UN 트랙 맨 왼쪽 칸에 마커를 놓습니다.\n각자 개인 보드의 환경 맨 왼쪽 위 칸에 오염 1개를 놓습니다.\n각자 일꾼 3개·에너지 2개를 받습니다. 나머지 일꾼·에너지는 따로 치워 둡니다.\n국가 카드 2장 중 1장, 업적 2개 중 1개를 고릅니다. 업적은 비공개, 남은 국가 카드는 요약표로 씁니다.\n고른 국가 카드의 시작 보너스를 받습니다.\n시작 플레이어부터 시계 방향으로 위 표의 시작 자금을 받습니다.","en":"Make supplies of resources, dice, Pollution and Oil Well tokens.\nShuffle the six card decks and the Achievement tiles separately.\nPlace 3 Early then 3 Late Global Impacts face down below the board. Return the rest to the box.\nFill each Structure market right to left with 3 cards from its deck.\nPlace 3 Achievements face up.\nEach player puts markers on 0 of the Score track and on the leftmost United Nations space.\nEach player places 1 Pollution in the top-left Environment space of their mat.\nEach player takes 3 Workers and 2 Energy. Keep the rest clearly apart.\nChoose 1 of 2 Nation cards and 1 of 2 Achievements. Keep the Achievement secret; the other Nation card is a reference.\nGain your Nation's starting bonus.\nStarting with the start player and going clockwise, take the starting money shown above."},"bscope":{"ko":"기념판 · 2–4인 기준 · 확장·솔로 제외","en":"Anniversary edition · 2–4 players · excludes expansions and solo","de":"Jubiläumsausgabe · 2–4 Spieler · ohne Erweiterungen/Solo","fr":"Édition anniversaire · 2–4 joueurs · hors extensions/solo","ja":"記念版・2～4人用・拡張とソロは対象外","es":"Edición aniversario · 2–4 jugadores · sin expansiones ni solitario","zh":"周年版 · 2–4人 · 不含扩展及单人模式"},"playerCount":{"ko":"인원","en":"Players","de":"Spieler","fr":"Joueurs","ja":"人数","es":"Jugadores","zh":"人数"},"tscope":{"ko":"디럭스 마스터 세트 기준 · 2–5인","en":"Deluxe Master Set · 2–5 players"},"tcalendar":{"ko":"검은색 달력 마커 시작 칸","en":"Dark Calendar marker start"},"tcal2":{"ko":"10번 칸","en":"Space 10"},"tcal3":{"ko":"11번 칸","en":"Space 11"},"tcal4":{"ko":"12번 칸","en":"Space 12"},"tcal5":{"ko":"12번 칸 · 1차 일식 후 11, 2차 일식 후 10으로 재설정","en":"Space 12 · reset to 11 after the 1st Eclipse, 10 after the 2nd"},"ttemple":{"ko":"신전 큰 칸 발견 타일","en":"Discovery tiles on temple major steps"},"ttemple24":{"ko":"인원 수에 맞게 쌓기 (기본 룰북)","en":"Stack per player count (base rulebook)"},"ttemple5":{"ko":"4인 수보다 칸마다 1개 더","en":"1 more per space than for 4 players"},"tpyramid":{"ko":"피라미드 구역 배치","en":"Pyramid grid layout"},"tpyr24":{"ko":"기본 룰북의 인원별 배치 그림","en":"Per-player-count diagram in the base rulebook"},"tpyr5":{"ko":"5인 전용 배치 (5인 확장 룰북 4·6쪽 그림)","en":"5-player pattern (5th Player rulebook pp. 4, 6)"},"tneutral":{"ko":"중립 일꾼 주사위","en":"Neutral worker dice"},"tneutral2":{"ko":"사용하지 않는 색 2가지 · 주사위 준비 카드로 배치","en":"Two unused colours · placed by the Neutral Worker card"},"tneutral3":{"ko":"사용하지 않는 색 1가지 · 주사위 준비 카드로 배치","en":"One unused colour · placed by the Neutral Worker card"},"tneutralNone":{"ko":"없음 (주사위 준비 카드는 상자에)","en":"None (Neutral Worker cards go back in the box)"},"tcacao":{"ko":"시작 카카오","en":"Starting cacao"},"tcacaoAll":{"ko":"마지막 플레이어 3개 · 나머지 2개","en":"Last player 3 · everyone else 2"},"tdraft":{"ko":"시작 카드 드래프트 (변형)","en":"Starting card draft (variant)"},"tdraft2":{"ko":"6장 펼치기","en":"Reveal 6 cards"},"tdraft3":{"ko":"8장 펼치기","en":"Reveal 8 cards"},"tdraft4":{"ko":"10장 펼치기","en":"Reveal 10 cards"},"tdraft5":{"ko":"12장 펼치기","en":"Reveal 12 cards"},"tcommon":{"ko":"메인 게임 판을 가운데 두고 옆에 신전 판을 놓습니다. 사용할 모듈의 구성물을 정리합니다.\n신전 보너스 타일을 위에서 두 번째 칸에 놓습니다.\n(2)–(7) 행동 판을 섞어 배치합니다.\n숭배 타일을 A·B·C로 나눠 섞고 1개씩 뽑아 (1) 행동 판에 앞면으로 놓습니다.\n기술 타일 6개를 무작위로 뽑아 번호 순서대로 (5) 행동 판에 앞면으로 놓습니다.\n흰색 달력 마커를 달력 트랙 0칸에, 검은색 달력 마커를 인원별 칸(위 표)에 놓습니다.\n메인 게임 판의 건물 칸을 가장 아래 칸만 빼고 채웁니다.\n피라미드 타일 3개를 앞면으로 공개하고, 피라미드 구역에 인원별 배치(위 표)로 타일을 놓습니다.\n조각상 타일 4개를 지정된 자리에 앞면으로 놓습니다.\n발견 타일을 행동 판의 지정된 자리에 1개씩 앞면으로 놓습니다.\n죽은 자의 거리 지정된 자리에 발견 타일을 아래부터 3개·2개·1개 쌓습니다.\n신전 트랙의 큰 칸에 발견 타일을 인원 수에 맞게 쌓습니다.\n각자 고른 색 구성물을 모두 가져와 점수 0, 피라미드 0, 죽은 자의 거리 0, 각 신전 바닥에 마커를 놓습니다.\n기술 마커를 개인 판 기술 칸에 1개씩 놓고, (5) 행동 판의 기술과 같은 기술 참조 타일을 1세트씩 가져옵니다.\n일꾼 주사위 1개는 눈 3으로 개인 판 지정 자리에 놓고, 나머지는 눈 1로 갖고 있습니다.\n시작 플레이어 토큰을 주고, 시계 방향 마지막 플레이어에게 마지막 플레이어 토큰을 줍니다.\n카카오: 마지막 플레이어 3개, 나머지 플레이어 2개.\n각자 시작 카드 4장을 받습니다. (중요) 발견 타일이 그려진 카드에는 무작위로 뽑아 붙여 둡니다.\n동시에 시작 카드 2장을 골라 혜택을 받고 나머지는 버립니다.\n턴 순서대로 남은 주사위를 시작 카드에 표시된 서로 다른 행동 판 세 곳에 1개씩 놓습니다.\n2·3인은 주사위 준비 카드를 뽑아 중립 주사위를 배치합니다.\n효과가 겹치면 기본 규칙 → 모듈 규칙 → 제사장 능력/약점 → 기술 효과·주황색 신전 능력 → 발견 타일 순으로 적용합니다.","en":"Place the main board in the middle with the temple board beside it. Sort the components for the modules you use.\nPlace the Temple Bonus tiles on the second space from the top.\nShuffle Action Boards (2)–(7) and lay them out.\nSort the Worship tiles into A, B and C, shuffle, and place one of each face up on Action Board (1).\nDraw 6 random Technology tiles and place them face up on Action Board (5) in number order.\nPut the light Calendar marker on space 0 and the dark one on the space for your player count (table above).\nFill the building spaces on the main board except the bottom row.\nReveal 3 Pyramid tiles and lay out the pyramid grid for your player count (table above).\nPlace 4 Decoration tiles face up on their spaces.\nPlace one Discovery tile face up on each marked Action Board space.\nStack Discovery tiles on the Avenue of the Dead: 3, 2 and 1 from the bottom.\nStack Discovery tiles on the temple major steps for your player count.\nEach player takes all components of their colour and places markers on score 0, pyramid 0, Avenue 0 and the bottom of each temple.\nPut one Technology marker on each technology space of your player board and take the matching set of Technology reference tiles for Action Board (5).\nPut one worker die showing 3 on your player board; keep the others showing 1.\nGive out the first-player token, and the last-player token to the last player clockwise.\nCacao: last player 3, everyone else 2.\nDeal 4 Starting cards each. Draw a random (Major) Discovery tile for any card that shows one.\nSimultaneously keep 2 Starting cards, take their benefits and discard the rest.\nIn turn order, place your remaining dice on the three different Action Boards shown on your Starting cards.\nWith 2 or 3 players, draw the Neutral Worker card to place the neutral dice.\nWhen effects overlap, apply: base rules → module rules → priest ability/weakness → technology or orange temple ability → Discovery tiles."},"tmodules":{"ko":"모듈 준비","en":"Module setup"},"tmodulesIntro":{"ko":"사용하는 모듈만 추가로 준비합니다.","en":"Add only the modules you play with."},"tmodulesSource":{"ko":"출처: 디럭스 마스터 세트 모듈 룰북 · 한국어 셋업 요약","en":"Source: Deluxe Master Set module rulebook · Korean setup sheet"},"tm1":{"ko":"M1 사제·여사제","en":"M1 Priests & Priestesses"},"tm1Setup":{"ko":"각자 제사장 타일 2개를 받아 동시에 1개를 고르고 나머지는 버립니다 (시작 카드 선택 후).","en":"Deal 2 priest tiles each; keep 1 simultaneously and discard the other (after choosing Starting cards)."},"tm2":{"ko":"M2 주황색 신전","en":"M2 Height of Development"},"tm2Setup":{"ko":"주황색 신전을 포함해 신전 보너스 타일과 신전 큰 칸 발견 타일을 놓습니다.","en":"Include the orange temple when placing Temple Bonus tiles and the Discovery tiles on major steps."},"tm3":{"ko":"M3 계절","en":"M3 Seasons of Progress"},"tm3Setup":{"ko":"계절 카드를 섞어 3장을 뒷면으로 쌓고 맨 위 카드를 공개합니다. 남은 준비 과정에 그 계절 효과를 적용합니다.","en":"Shuffle the Season cards, stack 3 face down and reveal the top one. Its effect applies to the rest of setup."},"tm7":{"ko":"M7 대저택","en":"M7 Mansion"},"tm7Setup":{"ko":"숭배 타일 3개를 (1) 행동 판에 섞어 앞면으로 놓고, 중요 발견 타일을 지정 자리에 놓습니다. 소유권 타일은 청·녹·적 신전 첫 번째 큰 칸에 놓습니다. 변형: (1) 행동 판도 함께 섞어 배치.","en":"Shuffle the 3 Worship tiles face up onto Action Board (1) and place the Major Discovery tile on its space. Put the Mansion Ownership tiles on the first major step of the blue, green and red temples. Variant: shuffle Action Board (1) in with the others."},"tm8":{"ko":"M8 제단·주술사","en":"M8 Altars & Shamans"},"tm8Setup":{"ko":"흑요석(M6)과 중요 발견 타일이 필요합니다. 행동 판 사이 큰 칸 4곳에 제단 타일을 무작위로 놓습니다 (가운데 화살표가 판 중앙을 향하게). 각 칸에 적힌 2/3/4인 수만큼 중요 발견 타일을 앞면으로 쌓습니다. 시작 카드(와 제사장) 선택 후 마지막 플레이어부터 빈 제단 칸에 주술사를 세워 놓습니다.","en":"Needs Obsidian (M6) and Major Discovery tiles. Place a random Altar on each of the 4 large spaces between Action Boards (arrow toward the board centre). Stack Major Discovery tiles face up on each space as printed for 2/3/4 players. After choosing Starting cards (and priests), in reverse order each player stands their Shaman on an empty Altar space."},"tm9":{"ko":"M9 제국 확장","en":"M9 Expanding the Empire"},"tm9Setup":{"ko":"제국 판을 메인 게임 판 옆에, 특별 가면 타일을 그 근처에 놓습니다. 시작 플레이어부터 제국 판의 테오티우아칸 지역에 전사 1명을 놓습니다.","en":"Place the Empire board next to the main board with the special Mask tiles nearby. From the first player, each places 1 warrior in the Teotihuacan region of the Empire board."},"tm10":{"ko":"M10 증원","en":"M10 Increased Workforce"},"tm10Setup":{"ko":"시작 카드 2장을 고른 뒤 각자 일꾼 1개를 상자에 넣고 시작 일꾼 2개만 놓습니다. 2–4인: 사용하지 않는 색마다 주사위 2개를 남기고, 시작 카드를 공개해 표시된 행동 판에 2개를 나눠 놓습니다 (\"2×6\"·\"2×7\"이면 다시 뽑기). 인원과 관계없이 주사위 준비 카드의 3인 면을 보고 빈 주사위 3개를 놓은 뒤 카드는 상자에 넣습니다.","en":"After choosing 2 Starting cards, each player returns 1 worker and places only 2 starting workers. 2–4 players: keep 2 dice per unused colour and place them on the Action Boards shown by a revealed Starting card (redraw on “2×6” or “2×7”). At any player count, place 3 blank dice using the 3-player side of a Neutral Worker card, then box those cards."},"tvariants":{"ko":"5인 · 변형 준비","en":"5 players & variants"},"tvariantsIntro":{"ko":"5인 확장 룰북과 모듈 룰북의 변형 규칙입니다.","en":"From the 5th Player Expansion and module rulebooks."},"tvariantsSource":{"ko":"출처: 5인 확장 룰북 3–6쪽 · 모듈 룰북 4쪽","en":"Source: 5th Player Expansion rulebook pp. 3–6 · module rulebook p. 4"},"t5simple":{"ko":"5인 간이 규칙","en":"Simplified 5-player rules"},"t5simpleSetup":{"ko":"4인 준비를 따르되 신전 큰 칸 발견 타일을 칸마다 1개 더 놓고, 피라미드는 5인 배치로 놓습니다. 주사위 준비 카드는 상자에 넣습니다. 일식 때 검은색 달력 마커를 1차 후 11, 2차 후 10에 놓습니다.","en":"Set up as for 4 players, but add 1 more Discovery tile to each temple major step and use the 5-player pyramid pattern. Return the Neutral Worker cards. At the Eclipse, reset the dark Calendar marker to 11 after the first and 10 after the second."},"t5m10":{"ko":"5인 + M10 증원","en":"5 players with M10"},"t5m10Setup":{"ko":"5인 간이 규칙의 판 준비에 M10 증원 준비를 더합니다. 공용(빈) 주사위로 카카오 경제 영향이 줄어듭니다.","en":"Use the 5-player board setup above plus the M10 setup. Common (blank) workers soften the impact on the cacao economy."},"tdraftRule":{"ko":"시작 카드 드래프트","en":"Starting card draft"},"tdraftRuleSetup":{"ko":"시작 카드 4장 분배와 선택을 대체합니다. 인원별 장수(위 표)를 펼치고, 발견 타일이 그려진 카드에는 바로 발견 타일을 뽑아 옆에 둡니다. 시작 플레이어부터 1장씩, 이어서 역순으로 1장씩 가져가고 (마지막 플레이어는 연속 2장) 혜택을 받습니다.","en":"Replaces dealing 4 Starting cards. Reveal the number of cards for your player count (table above) and draw a Discovery tile next to each card that shows one. Pick 1 each from the first player, then 1 each in reverse order (the last player takes 2 in a row), and take the benefits."},"texpertPyramid":{"ko":"숙련자 피라미드","en":"Expert pyramid setup"},"texpertPyramidSetup":{"ko":"피라미드 구역을 모듈 룰북 4쪽의 인원별 숙련자 배치로 놓습니다.","en":"Lay out the pyramid grid using the expert pattern for your player count (module rulebook p. 4)."}},"games":{"burgundy":{"rows":[["board","b2","b3","b4"],["depot6","normal","b3swap","normal"],["workers",{"value":"1 / 2"},{"value":"1 / 2 / 3"},{"value":"1 / 2 / 3 / 4"}]],"common":"bcommon","source":{"url":"https://images.amainhobbies.com/images/resources/RVB26925/Manuals/1-RVB26925_The_Castles_of_Burgundy_Board_Game_Manual.pdf","pages":[2,3,11],"edition":"2019 anniversary"},"scope":"bscope"},"gah":{"rows":[["dice",{"value":"10"},{"value":"12"},{"value":"14"}],["order","o2","o3","o4"],["guest",{"value":"2 → 1"},{"value":"3 → 2 → 1"},{"value":"4 → 3 → 2 → 1"}]],"common":"gcommon","source":{"url":"https://cdn.1j1ju.com/medias/fa/5d/33-grand-austria-hotel-rulebook.pdf","pages":[4,5,6],"edition":"Lookout base rules"}},"marrakesh":{"rows":[["oasis",{"value":"3"},{"value":"2"},{"value":"2"}],["draw","drawrule","drawrule","drawrule"]],"common":"mcommon","source":{"url":"https://rules.queen-games.com/marrakesh_en.pdf","pages":[4,5],"edition":"Queen Games base rules"},"scope":"mscope","expansions":[{"id":"camels-nomads","title":"mexp1","intro":"mexp1Intro","sourceText":"mexp1Source","source":{"type":"user-provided-rulebook","title":"Marrakesh: Camels & Nomads","filename":"marrakesh_exp1_camels+nomads_en.pdf","pages":[1,2,5,7,8]},"modules":[{"id":"nomads","name":"mnomads","setup":"mnomadsSetup","page":1},{"id":"camels","name":"mcamels","setup":"mcamelsSetup","page":2},{"id":"buildings","name":"mbuildings","setup":"mbuildingsSetup","page":5},{"id":"provisions","name":"mprovisions","setup":"mprovisionsSetup","page":7},{"id":"luxury","name":"mluxury","setup":"mluxurySetup","page":8},{"id":"oases","name":"moases","setup":"moasesSetup","page":8}]},{"id":"expansion-2","title":"mexp2","intro":"mexp2Intro","sourceText":"mexp2Source","source":{"type":"user-provided-rulebook-images","url":"https://rules.queen-games.com/marrakesh_exp2_en.pdf","images":["3345.jpg","3346.jpg","3347.jpg","3348.jpg","3349.jpg","3350.jpg","3351.jpg"]},"modules":[{"id":"closed-madrasa","name":"mclosedMadrasa","setup":"mclosedMadrasaSetup"},{"id":"gems","name":"mgems","setup":"mgemsSetup"},{"id":"experts","name":"mexperts","setup":"mexpertsSetup"},{"id":"alms","name":"malms","setup":"malmsSetup"},{"id":"second-hand-shop","name":"msecondhand","setup":"msecondhandSetup"},{"id":"gifts","name":"mgifts","setup":"mgiftsSetup"}]}]},"energy-empire":{"players":[2,3,4,5],"rows":[["epollution",{"value":"4"},{"value":"5"},{"value":"6"},{"value":"7"}],["eneutral","eneutral2","enone","enone","enone"],["emoney",{"value":"0 / $1"},{"value":"0 / $1 / $2"},{"value":"0 / $1 / $2 / $3"},{"value":"0 / $1 / $2 / $3 / $4"}]],"common":"ecommon","scope":"escope","source":{"file":"EnergyEmpireRules.pdf","pages":[4,5],"edition":"base rules"}},"teotihuacan":{"players":[2,3,4,5],"rows":[["tcalendar","tcal2","tcal3","tcal4","tcal5"],["tpyramid","tpyr24","tpyr24","tpyr24","tpyr5"],["ttemple","ttemple24","ttemple24","ttemple24","ttemple5"],["tneutral","tneutral2","tneutral3","tneutralNone","tneutralNone"],["tcacao","tcacaoAll","tcacaoAll","tcacaoAll","tcacaoAll"],["tdraft","tdraft2","tdraft3","tdraft4","tdraft5"]],"common":"tcommon","scope":"tscope","source":{"type":"user-provided-setup-sheet","rulebooks":["Teotihuacan Deluxe Master Set modules rulebook pp. 4, 13–14","teo_deluxe_5th_player_rulebook.pdf pp. 3–6"]},"expansions":[{"id":"modules","title":"tmodules","intro":"tmodulesIntro","sourceText":"tmodulesSource","modules":[{"id":"m1","name":"tm1","setup":"tm1Setup"},{"id":"m2","name":"tm2","setup":"tm2Setup"},{"id":"m3","name":"tm3","setup":"tm3Setup"},{"id":"m7","name":"tm7","setup":"tm7Setup"},{"id":"m8","name":"tm8","setup":"tm8Setup"},{"id":"m9","name":"tm9","setup":"tm9Setup"},{"id":"m10","name":"tm10","setup":"tm10Setup"}]},{"id":"variants","title":"tvariants","intro":"tvariantsIntro","sourceText":"tvariantsSource","modules":[{"id":"five-simple","name":"t5simple","setup":"t5simpleSetup"},{"id":"five-m10","name":"t5m10","setup":"t5m10Setup"},{"id":"draft","name":"tdraftRule","setup":"tdraftRuleSetup"},{"id":"expert-pyramid","name":"texpertPyramid","setup":"texpertPyramidSetup"}]}]}}};
